import {identitySpec,componentSpecs,buildSpec,circuitTypes,emptyInstrumentWorkspace,mappingReport,scaleToMM,displayScale} from './instrument-workspace.mjs';
export function createInstrumentWorkspaceUI({doc,snapshot,workspace=emptyInstrumentWorkspace(),onChange=()=>{},readonly=false}={}){
 let draft=structuredClone(workspace);const e=(tag,text)=>{const n=doc.createElement(tag);if(text!=null)n.textContent=text;return n;},overview=e('section'),electronics=e('section'),build=e('section'),report=e('div'),rows=e('div'),buildRows=e('div');
 const labels={strings:'Number of strings',scale_mm:'Scale length',scale_unit:'Scale length display unit',tuning:'Tuning',handedness:'Handedness',measured_dcr_ohm:'Measured DC resistance (ohm)',measured_inductance_h:'Measured inductance (H)',nominal_ohm:'Nominal resistance (ohm)',measured_ohm:'Measured resistance (ohm)',nominal_pf:'Nominal capacitance (pF)',measured_pf:'Measured capacitance (pF)',tolerance_percent:'Tolerance (%)',voltage_v:'Voltage rating (V)',capacitor_id:'Associated physical capacitor',resistor_id:'Associated physical resistor',installed_on:'Installation date (if recorded)'};
 const label=k=>labels[k]||k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
 const summary=e('p');function changed(){onChange(structuredClone(draft));drawReport();}
 function control(parent,key,spec,value,assign,{prefix='',options}={}){const l=e('label',label(key)),n=e(spec.options||options?'select':spec.text>=2000?'textarea':'input');n.name=prefix+key;if(spec.options||options){const o=e('option','Unknown / not recorded');o.value='';n.append(o);for(const v of options||spec.options){const o=e('option',typeof v==='object'?v.label:v);o.value=typeof v==='object'?v.value:v;n.append(o);}}else{n.type=spec.number?'number':spec.date?'date':'text';if(spec.number){n.min=String(spec.number[0]);n.max=String(spec.number[1]);n.step=spec.integer?'1':'any';}if(spec.text)n.maxLength=spec.text;}n.value=value??'';n.disabled=readonly;n.addEventListener('input',()=>{const v=n.value===''?null:spec.number?Number(n.value):n.value;assign(v);changed();});n.addEventListener('change',()=>{const v=n.value===''?null:spec.number?Number(n.value):n.value;assign(v);changed();});l.append(n);parent.append(l);return n;}
 function button(parent,text,run){const b=e('button',text);b.type='button';b.disabled=readonly;b.addEventListener('click',run);parent.append(b);return b;}
 overview.append(e('h3','Instrument overview'),summary,e('p',snapshot.metadata.title),e('p',snapshot.technical.summary),e('p',snapshot.technical.limits),e('p','Identity and physical documentation are owner-entered facts. Unknown fields remain unrecorded. Documentation does not enable unsupported response analysis.'));
 const identity=e('fieldset');identity.append(e('legend','Optional instrument specifications'));overview.append(identity);
 const scaleUnit=draft.identity.scale_unit||'mm';let scaleInput;
 for(const [key,spec] of Object.entries(identitySpec)){if(key==='scale_mm'){scaleInput=control(identity,key,{number:[0.001,1500]},displayScale(draft.identity.scale_mm,scaleUnit),v=>{draft.identity.scale_mm=v==null?null:scaleToMM(v,draft.identity.scale_unit||'mm');},{prefix:'identity_'});}else if(key==='scale_unit'){control(identity,key,spec,scaleUnit,v=>{draft.identity.scale_unit=v;scaleInput.value=displayScale(draft.identity.scale_mm,v||'mm');},{prefix:'identity_'});}else control(identity,key,spec,draft.identity[key],v=>{draft.identity[key]=v;},{prefix:'identity_'});}
 electronics.append(e('h3','Physical electronics inventory'),e('p','Physical instance IDs are separate from circuit component IDs and catalogue products. A mapping documents an association; it never changes circuit connections. Nominal specifications and manual measurements are distinct.'),report,rows);
 const kind=e('select');kind.setAttribute('aria-label','New physical component type');for(const k of Object.keys(componentSpecs)){const o=e('option',label(k));o.value=k;kind.append(o);}kind.disabled=readonly;electronics.append(kind);button(electronics,'Add physical component',()=>{draft.components.push({id:globalThis.crypto.randomUUID(),kind:kind.value,status:'unknown',circuit_id:null,fields:{}});drawComponents();changed();});
 function drawReport(){summary.textContent=draft.components.length+' documented physical components · '+draft.components.filter(c=>c.status==='installed').length+' explicitly recorded as installed · '+draft.build.length+' build/service entries.';report.replaceChildren();const r=mappingReport(draft,snapshot.technical);report.append(e('p',r.inventoryOnly.length+' inventory-only · '+r.circuitOnly.length+' circuit-only · '+r.missing.length+' stale mappings · '+r.removed.length+' removed instances still mapped.'));for(const c of r.missing)report.append(e('p','Reconcile stale mapping '+c.circuit_id+' on physical instance '+c.id+' before saving.'));}
 function drawComponents(){rows.replaceChildren();for(const c of draft.components){const item=e('details');item.open=true;item.dataset.physicalInstance=c.id;item.append(e('summary',label(c.kind)+' · '+c.id));control(item,'status',{options:['unknown','installed','planned','removed']},c.status,v=>{c.status=v;},{prefix:c.id+'_'});control(item,'circuit_id',{},c.circuit_id,v=>{c.circuit_id=v;},{prefix:c.id+'_',options:[...snapshot.technical.components.filter(x=>c.kind==='other'||circuitTypes[c.kind].includes(x.type)).map(x=>({value:x.id,label:x.label+' · '+x.id})),...(c.circuit_id&&!snapshot.technical.components.some(x=>x.id===c.circuit_id)?[{value:c.circuit_id,label:'STALE · '+c.circuit_id}]:[])]});for(const [key,spec] of Object.entries(componentSpecs[c.kind])){const associated=spec.uuid?draft.components.filter(x=>x.kind===(key==='capacitor_id'?'capacitor':'resistor')&&x.id!==c.id).map(x=>({value:x.id,label:(x.fields.model||x.kind)+' · '+x.id})):undefined;control(item,key,spec,c.fields[key],v=>{c.fields[key]=v;},{prefix:c.id+'_',options:associated});}button(item,'Refresh association choices',()=>{drawComponents();});button(item,'Mark no longer installed',()=>{if(doc.defaultView.confirm('Mark this physical component as no longer installed? Saved revisions remain unchanged.')){c.status='removed';drawComponents();changed();}});button(item,'Remove component from draft',()=>{if(doc.defaultView.confirm('Remove this component from the editable draft? Existing revisions retain it. Associated records may need reconciliation.')){draft.components=draft.components.filter(x=>x.id!==c.id);drawComponents();changed();}});rows.append(item);}if(!draft.components.length)rows.append(e('p','No physical components recorded. Circuit requirements are not automatically installed inventory.'));}
 build.append(e('h3','Build and service record'),e('p','User-entered work and manual measurements. No inspection, installation, testing or certification is implied by the presence of a circuit.'),buildRows);button(build,'Add build / service entry',()=>{draft.build.push({id:globalThis.crypto.randomUUID(),fields:{}});drawBuild();changed();});
 function drawBuild(){buildRows.replaceChildren();for(const b of draft.build){const item=e('details');item.open=true;item.append(e('summary','Recorded work · '+b.id));for(const [key,spec] of Object.entries(buildSpec))control(item,key,spec,b.fields[key],v=>{b.fields[key]=v;},{prefix:b.id+'_'});button(item,'Remove build entry from draft',()=>{if(doc.defaultView.confirm('Remove this editable build entry? Saved revision history remains unchanged.')){draft.build=draft.build.filter(x=>x.id!==b.id);drawBuild();changed();}});buildRows.append(item);}if(!draft.build.length)buildRows.append(e('p','No build or service work recorded.'));}
 drawComponents();drawBuild();drawReport();return {overview,electronics,build,value:()=>structuredClone(draft)};
}
export function renderHistoricalInstrument(doc,revision,workspace){const section=doc.createElement('details'),heading=doc.createElement('summary');heading.textContent='Read-only configuration · V'+revision.sequence;section.append(heading);for(const [title,value] of [['Core instrument and circuit snapshot',revision.snapshot],['Physical documentation captured for this exact revision',workspace||'Not recorded for this revision']]){const h=doc.createElement('h4'),pre=doc.createElement('pre');h.textContent=title;pre.textContent=typeof value==='string'?value:JSON.stringify(value,null,2);section.append(h,pre);}return section;}
export function renderInstrumentBuildRecord({project_id,revision_id,workspace}){const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return '<section><h2>Physical instrument documentation · USER-ENTERED</h2><p>Project '+escape(project_id)+' · exact revision '+escape(revision_id)+'</p><p>Nominal specifications and manual measurements are distinct. No physical inspection, test, installation or certification is inferred.</p><pre>'+escape(JSON.stringify(workspace,null,2))+'</pre></section>';}
